-- MOSTARDA — 35+ Stored Procedures (7 módulos)
-- Revenue Split: Mostarda 25% | Space Owner 25% | TV Owner 20% | Affiliate 20% | Influencer 10%

CREATE SCHEMA IF NOT EXISTS api;

-- Pricing Engine
CREATE OR REPLACE FUNCTION api.location_multiplier(category text) RETURNS double precision LANGUAGE SQL IMMUTABLE AS $$ SELECT CASE category WHEN 'mall' THEN 1.8 WHEN 'gym' THEN 1.5 WHEN 'restaurant' THEN 1.3 WHEN 'bar' THEN 1.4 WHEN 'airport' THEN 2.0 WHEN 'bus_station' THEN 1.6 WHEN 'hospital' THEN 1.2 WHEN 'school' THEN 1.1 WHEN 'office' THEN 1.3 WHEN 'market' THEN 1.4 WHEN 'hotel' THEN 1.5 WHEN 'theater' THEN 1.3 ELSE 1.0 END $$;

CREATE OR REPLACE FUNCTION api.time_score(hour integer) RETURNS double precision LANGUAGE SQL IMMUTABLE AS $$ SELECT CASE hour WHEN 6 THEN 0.6 WHEN 7 THEN 0.8 WHEN 8 THEN 1.0 WHEN 9 THEN 1.2 WHEN 10 THEN 1.3 WHEN 11 THEN 1.4 WHEN 12 THEN 1.5 WHEN 13 THEN 1.4 WHEN 14 THEN 1.3 WHEN 15 THEN 1.2 WHEN 16 THEN 1.3 WHEN 17 THEN 1.5 WHEN 18 THEN 1.8 WHEN 19 THEN 2.0 WHEN 20 THEN 1.9 WHEN 21 THEN 1.7 WHEN 22 THEN 1.4 WHEN 23 THEN 1.0 ELSE 1.0 END $$;

CREATE OR REPLACE FUNCTION api.seasonality_score(month integer) RETURNS double precision LANGUAGE SQL IMMUTABLE AS $$ SELECT CASE month WHEN 1 THEN 1.2 WHEN 2 THEN 1.1 WHEN 3 THEN 1.0 WHEN 4 THEN 0.9 WHEN 5 THEN 0.9 WHEN 6 THEN 1.0 WHEN 7 THEN 1.1 WHEN 8 THEN 1.0 WHEN 9 THEN 1.0 WHEN 10 THEN 1.1 WHEN 11 THEN 1.2 WHEN 12 THEN 1.5 ELSE 1.0 END $$;

CREATE OR REPLACE FUNCTION api.calculate_dynamic_price(p_base_price bigint, p_location_score double precision, p_audience_score double precision, p_demand_score double precision, p_time_score double precision, p_seasonality_score double precision, p_historical_fill_rate double precision) RETURNS bigint LANGUAGE SQL IMMUTABLE AS $$ SELECT GREATEST(50, ROUND(p_base_price * (0.5 + p_location_score * 0.75) * (0.5 + p_audience_score * 0.75) * (0.5 + p_time_score * 0.75) * (0.8 + p_demand_score * 0.6) * p_seasonality_score * (0.7 + p_historical_fill_rate * 0.6))::bigint) $$;

CREATE OR REPLACE FUNCTION api.recalculate_tv_prices(p_tv_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_updated integer := 0; v_slot record; v_factors jsonb; v_new_price bigint; BEGIN FOR v_slot IN SELECT * FROM public.tv_slots WHERE tv_id = p_tv_id AND date = p_date LOOP v_factors := api.calculate_pricing_factors(p_tv_id, p_date, v_slot.start_time); v_new_price := api.calculate_dynamic_price(v_slot.base_price, (v_factors->>'location_score')::double precision, (v_factors->>'audience_score')::double precision, (v_factors->>'demand_score')::double precision, (v_factors->>'time_score')::double precision, (v_factors->>'seasonality_score')::double precision, (v_factors->>'historical_fill_rate')::double precision); UPDATE public.tv_slots SET current_price = v_new_price, updated_at = now_utc() WHERE id = v_slot.id; INSERT INTO public.pricing_history (tv_id, slot_id, date, time_of_day, base_price, calculated_price, factors, calculated_at) VALUES (p_tv_id, v_slot.id, p_date, v_slot.start_time, v_slot.base_price, v_new_price, v_factors, now_utc()); v_updated := v_updated + 1; END LOOP; RETURN jsonb_build_object('updated', v_updated, 'date', p_date); END $$;

CREATE OR REPLACE FUNCTION api.get_tv_pricing(p_tv_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'start_time', start_time, 'end_time', end_time, 'status', status, 'current_price', current_price) ORDER BY start_time), '[]'::jsonb) FROM public.tv_slots WHERE tv_id = p_tv_id AND date = p_date $$;

-- Campaigns
CREATE OR REPLACE FUNCTION api.create_campaign(p_advertiser_id uuid, p_name text, p_brand_name text, p_budget bigint, p_description text DEFAULT NULL, p_brand_website text DEFAULT NULL, p_preferred_categories text[] DEFAULT NULL, p_preferred_cities text[] DEFAULT NULL, p_preferred_states text[] DEFAULT NULL, p_auto_optimize boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE v_campaign_id uuid; BEGIN IF p_budget < 2000 THEN RAISE EXCEPTION 'Minimum budget is R$20,00. Got R$%', (p_budget / 100)::numeric(10,2); END IF; INSERT INTO public.campaigns (advertiser_id, name, description, brand_name, brand_website, budget, remaining_budget, status, preferred_categories, preferred_cities, preferred_states, day_parts, auto_optimize, created_at, updated_at) VALUES (p_advertiser_id, p_name, p_description, p_brand_name, p_brand_website, p_budget, p_budget, 'draft', p_preferred_categories, p_preferred_cities, p_preferred_states, p_preferred_cities, p_auto_optimize, now_utc(), now_utc()) RETURNING id INTO v_campaign_id; RETURN v_campaign_id; END $$;

CREATE OR REPLACE FUNCTION api.activate_campaign(p_campaign_id uuid) RETURNS jsonb LANGUAGE plpgsql AS $$ BEGIN UPDATE public.campaigns SET status = 'active', updated_at = now_utc() WHERE id = p_campaign_id AND status = 'draft'; IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found or not in draft'; END IF; RETURN jsonb_build_object('success', true); END $$;

CREATE OR REPLACE FUNCTION api.book_slot(p_campaign_id uuid, p_slot_id uuid, p_price_paid bigint) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_campaign record; v_slot record; v_campaign_slot_id uuid; BEGIN SELECT * INTO v_campaign FROM public.campaigns WHERE id = p_campaign_id; IF NOT FOUND THEN RAISE EXCEPTION 'Campaign not found'; END IF; SELECT * INTO v_slot FROM public.tv_slots WHERE id = p_slot_id; IF NOT FOUND THEN RAISE EXCEPTION 'Slot not found'; END IF; IF v_slot.status != 'available' THEN RAISE EXCEPTION 'Slot not available'; END IF; INSERT INTO public.campaign_slots (campaign_id, slot_id, tv_id, price_paid, is_confirmed, booked_at) VALUES (p_campaign_id, p_slot_id, v_slot.tv_id, p_price_paid, true, now_utc()) RETURNING id INTO v_campaign_slot_id; UPDATE public.tv_slots SET status = 'booked', campaign_id = p_campaign_id, campaign_slot_id = v_campaign_slot_id, current_price = p_price_paid, updated_at = now_utc() WHERE id = p_slot_id; UPDATE public.campaigns SET remaining_budget = remaining_budget - p_price_paid, total_slots_booked = COALESCE(total_slots_booked, 0) + 1, total_spent = COALESCE(total_spent, 0) + p_price_paid, updated_at = now_utc() WHERE id = p_campaign_id; RETURN jsonb_build_object('campaign_slot_id', v_campaign_slot_id, 'remaining_budget', v_campaign.remaining_budget - p_price_paid); END $$;

CREATE OR REPLACE FUNCTION api.update_campaign_status(p_campaign_id uuid, p_status campaign_status) RETURNS jsonb LANGUAGE plpgsql AS $$ BEGIN UPDATE public.campaigns SET status = p_status, updated_at = now_utc() WHERE id = p_campaign_id; RETURN jsonb_build_object('success', true); END $$;

CREATE OR REPLACE FUNCTION api.get_advertiser_campaigns(p_advertiser_id uuid) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY created_at DESC), '[]'::jsonb) FROM public.campaigns c WHERE c.advertiser_id = p_advertiser_id $$;

-- Elections
CREATE OR REPLACE FUNCTION api.create_election(p_tv_id uuid, p_start_date date, p_end_date date) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE v_election_id uuid; v_incumbents jsonb := '[]'::jsonb; BEGIN IF EXISTS (SELECT 1 FROM public.elections WHERE tv_id = p_tv_id AND status = 'active') THEN RAISE EXCEPTION 'Active election exists'; END IF; INSERT INTO public.elections (tv_id, status, start_date, end_date, candidates, created_at, updated_at) VALUES (p_tv_id, 'active', p_start_date, p_end_date, v_incumbents, now_utc(), now_utc()) RETURNING id INTO v_election_id; RETURN v_election_id; END $$;

CREATE OR REPLACE FUNCTION api.nominate_candidate(p_election_id uuid, p_nominee_id uuid, p_nominated_by uuid, p_platform text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_election record; v_has_role boolean; v_nominee record; BEGIN SELECT * INTO v_election FROM public.elections WHERE id = p_election_id; IF NOT FOUND THEN RAISE EXCEPTION 'Election not found'; END IF; SELECT EXISTS (SELECT 1 FROM public.actor_assignments WHERE user_id = p_nominated_by AND is_active = true AND role IN ('space_owner','tv_owner','affiliate_seller')) INTO v_has_role; IF NOT v_has_role THEN RAISE EXCEPTION 'Only Space/TV/Affiliate can nominate'; END IF; UPDATE public.elections SET candidates = candidates || jsonb_build_object('user_id', p_nominee_id, 'name', COALESCE((SELECT name FROM public.users WHERE id = p_nominee_id), 'Candidate'), 'platform', COALESCE(p_platform, 'Minha proposta'), 'vote_count', 0, 'weighted_vote_count', 0, 'is_incumbent', false, 'nominated_at', now_utc()), updated_at = now_utc() WHERE id = p_election_id; RETURN jsonb_build_object('success', true); END $$;

CREATE OR REPLACE FUNCTION api.cast_vote(p_election_id uuid, p_tv_id uuid, p_voter_id uuid, p_voter_type text, p_candidate_id uuid) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_election record; v_weight double precision := 1.0; v_role record; BEGIN SELECT * INTO v_election FROM public.elections WHERE id = p_election_id; IF NOT FOUND THEN RAISE EXCEPTION 'Election not found'; END IF; IF EXISTS (SELECT 1 FROM public.votes WHERE election_id = p_election_id AND voter_id = p_voter_id) THEN RAISE EXCEPTION 'Already voted'; END IF; FOR v_role IN SELECT role FROM public.actor_assignments WHERE user_id = p_voter_id AND is_active = true LOOP v_weight := CASE v_role.role WHEN 'space_owner' THEN GREATEST(v_weight, 3.0) WHEN 'tv_owner' THEN GREATEST(v_weight, 2.5) WHEN 'affiliate_seller' THEN GREATEST(v_weight, 2.0) ELSE v_weight END; END LOOP; INSERT INTO public.votes (election_id, tv_id, voter_id, voter_type, candidate_id, weight, voted_at) VALUES (p_election_id, p_tv_id, p_voter_id, p_voter_type, p_candidate_id, v_weight, now_utc()); UPDATE public.elections SET total_votes = total_votes + 1, total_weighted_votes = total_weighted_votes + v_weight, updated_at = now_utc() WHERE id = p_election_id; RETURN jsonb_build_object('success', true, 'weight', v_weight); END $$;

CREATE OR REPLACE FUNCTION api.close_election(p_election_id uuid) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_election record; v_winner_id uuid; BEGIN SELECT * INTO v_election FROM public.elections WHERE id = p_election_id; SELECT (c->>'user_id')::uuid INTO v_winner_id FROM jsonb_array_elements(v_election.candidates) AS c ORDER BY (c->>'weighted_vote_count')::double precision DESC LIMIT 1; UPDATE public.elections SET status = 'closed', winner_id = v_winner_id, updated_at = now_utc() WHERE id = p_election_id; RETURN jsonb_build_object('winner', v_winner_id, 'total_votes', v_election.total_votes); END $$;

-- Wallet & Revenue
CREATE OR REPLACE FUNCTION api.initialize_wallet(p_user_id uuid) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE v_wallet_id uuid; BEGIN INSERT INTO public.wallets (user_id, balance, updated_at) VALUES (p_user_id, 0, now_utc()) ON CONFLICT (user_id) DO UPDATE SET updated_at = now_utc() RETURNING id INTO v_wallet_id; RETURN v_wallet_id; END $$;

CREATE OR REPLACE FUNCTION api.deposit_to_wallet(p_user_id uuid, p_amount bigint, p_description text) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_wallet record; v_balance_before bigint; BEGIN INSERT INTO public.wallets (user_id, balance, updated_at) VALUES (p_user_id, 0, now_utc()) ON CONFLICT (user_id) DO NOTHING; SELECT * INTO v_wallet FROM public.wallets WHERE user_id = p_user_id; v_balance_before := v_wallet.balance; UPDATE public.wallets SET balance = balance + p_amount, total_deposited = total_deposited + p_amount, updated_at = now_utc() WHERE id = v_wallet.id; INSERT INTO public.transactions (user_id, wallet_id, type, amount, balance_before, balance_after, description, created_at) VALUES (p_user_id, v_wallet.id, 'deposit', p_amount, v_balance_before, v_balance_before + p_amount, p_description, now_utc()); RETURN jsonb_build_object('balance', v_balance_before + p_amount); END $$;

CREATE OR REPLACE FUNCTION api.distribute_slot_revenue(p_campaign_slot_id uuid, p_tv_id uuid, p_slot_id uuid, p_total_amount bigint) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_tv record; v_location record; v_campaign_slot record; v_campaign record; v_dist jsonb := '[]'::jsonb; v_revenue_split_id uuid; v_wallet record; v_balance_before bigint; v_user record; BEGIN SELECT * INTO v_tv FROM public.tvs WHERE id = p_tv_id; SELECT * INTO v_location FROM public.locations WHERE id = v_tv.location_id; SELECT * INTO v_campaign_slot FROM public.campaign_slots WHERE id = p_campaign_slot_id; SELECT * INTO v_campaign FROM public.campaigns WHERE id = v_campaign_slot.campaign_id; v_dist := v_dist || jsonb_build_object('actor_id', v_tv.owner_id, 'role', 'tv_owner', 'percentage', 0.20, 'amount', ROUND(p_total_amount * 0.20), 'paid', false); IF v_location.id IS NOT NULL THEN v_dist := v_dist || jsonb_build_object('actor_id', v_location.space_owner_id, 'role', 'space_owner', 'percentage', 0.25, 'amount', ROUND(p_total_amount * 0.25), 'paid', false); END IF; IF v_campaign.affiliate_seller_id IS NOT NULL THEN v_dist := v_dist || jsonb_build_object('actor_id', v_campaign.affiliate_seller_id, 'role', 'affiliate_seller', 'percentage', 0.20, 'amount', ROUND(p_total_amount * 0.20), 'paid', false); END IF; IF v_campaign.influencer_id IS NOT NULL THEN v_dist := v_dist || jsonb_build_object('actor_id', v_campaign.influencer_id, 'role', 'influencer', 'percentage', 0.10, 'amount', ROUND(p_total_amount * 0.10), 'paid', false); ELSE DECLARE v_winner_id uuid; BEGIN SELECT winner_id INTO v_winner_id FROM public.elections WHERE tv_id = p_tv_id AND status = 'closed' AND winner_id IS NOT NULL ORDER BY created_at DESC LIMIT 1; IF v_winner_id IS NOT NULL THEN v_dist := v_dist || jsonb_build_object('actor_id', v_winner_id, 'role', 'influencer', 'percentage', 0.10, 'amount', ROUND(p_total_amount * 0.10), 'paid', false); END IF; END; END IF; INSERT INTO public.revenue_splits (campaign_slot_id, slot_id, tv_id, total_amount, distributions, created_at) VALUES (p_campaign_slot_id, p_slot_id, p_tv_id, p_total_amount, v_dist, now_utc()) RETURNING id INTO v_revenue_split_id; FOR v_user IN SELECT (elem->>'actor_id')::uuid AS user_id, (elem->>'role')::text AS role, (elem->>'amount')::bigint AS amount, (elem->>'percentage')::double precision AS percentage FROM jsonb_array_elements(v_dist) AS elem WHERE (elem->>'amount')::bigint > 0 LOOP INSERT INTO public.wallets (user_id, balance, updated_at) VALUES (v_user.user_id, 0, now_utc()) ON CONFLICT (user_id) DO NOTHING; SELECT * INTO v_wallet FROM public.wallets WHERE user_id = v_user.user_id; v_balance_before := v_wallet.balance; UPDATE public.wallets SET balance = balance + v_user.amount, total_deposited = total_deposited + v_user.amount, updated_at = now_utc() WHERE id = v_wallet.id; INSERT INTO public.transactions (user_id, wallet_id, type, amount, balance_before, balance_after, description, reference_id, reference_type, created_at) VALUES (v_user.user_id, v_wallet.id, 'revenue_split', v_user.amount, v_balance_before, v_balance_before + v_user.amount, format('Receita slot — %s (%s%%)', v_user.role, ROUND(v_user.percentage * 100)), v_revenue_split_id::text, 'revenue_split', now_utc()); UPDATE public.users SET total_earned = COALESCE(total_earned, 0) + v_user.amount WHERE id = v_user.user_id; END LOOP; UPDATE public.revenue_splits SET is_distributed = true, distributed_at = now_utc() WHERE id = v_revenue_split_id; UPDATE public.campaign_slots SET revenue_distributed = true WHERE id = p_campaign_slot_id; RETURN jsonb_build_object('revenue_split_id', v_revenue_split_id, 'distributions', v_dist); END $$;

-- Device Monitor
CREATE OR REPLACE FUNCTION api.register_heartbeat(p_tv_id uuid, p_heartbeat_type heartbeat_type, p_timestamp bigint, p_is_online boolean DEFAULT true, p_cpu_usage double precision DEFAULT NULL, p_memory_usage double precision DEFAULT NULL, p_metadata jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql AS $$ BEGIN INSERT INTO public.device_heartbeats (tv_id, heartbeat_type, timestamp, is_online, cpu_usage, memory_usage, metadata) VALUES (p_tv_id, p_heartbeat_type, p_timestamp, p_is_online, p_cpu_usage, p_memory_usage, p_metadata); UPDATE public.tvs SET is_online = p_is_online, last_heartbeat = p_timestamp, status = CASE WHEN p_is_online THEN 'active'::tv_status ELSE 'offline'::tv_status END, updated_at = now_utc() WHERE id = p_tv_id; RETURN jsonb_build_object('success', true); END $$;

CREATE OR REPLACE FUNCTION api.report_anomaly(p_tv_id uuid, p_type text, p_severity anomaly_severity, p_description text, p_details jsonb DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE v_tv record; v_anomaly_id uuid; BEGIN SELECT * INTO v_tv FROM public.tvs WHERE id = p_tv_id; INSERT INTO public.anomalies (tv_id, location_id, type, severity, description, details, created_at) VALUES (p_tv_id, v_tv.location_id, p_type, p_severity, p_description, p_details, now_utc()) RETURNING id INTO v_anomaly_id; RETURN v_anomaly_id; END $$;

CREATE OR REPLACE FUNCTION api.get_tv_health_status(p_tv_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$ DECLARE v_tv record; v_active_anomalies jsonb; v_today_start bigint; v_has_start boolean; v_has_midpoint boolean; v_has_end boolean; BEGIN SELECT * INTO v_tv FROM public.tvs WHERE id = p_tv_id; SELECT jsonb_agg(to_jsonb(a)) INTO v_active_anomalies FROM public.anomalies a WHERE a.tv_id = p_tv_id AND a.is_resolved = false; v_today_start := EXTRACT(EPOCH FROM CURRENT_DATE)::bigint * 1000; SELECT COUNT(*) FILTER (WHERE heartbeat_type = 'start') > 0, COUNT(*) FILTER (WHERE heartbeat_type = 'midpoint') > 0, COUNT(*) FILTER (WHERE heartbeat_type = 'end') > 0 INTO v_has_start, v_has_midpoint, v_has_end FROM public.device_heartbeats WHERE tv_id = p_tv_id AND timestamp >= v_today_start; RETURN jsonb_build_object('name', v_tv.name, 'status', v_tv.status, 'is_online', v_tv.is_online, 'active_anomalies', COALESCE(jsonb_array_length(v_active_anomalies), 0), 'heartbeats_today', jsonb_build_object('start', v_has_start, 'midpoint', v_has_midpoint, 'end', v_has_end)); END $$;

-- Blockchain
CREATE OR REPLACE FUNCTION api.store_proof_of_play(p_tv_identifier text, p_slot_id uuid, p_timestamp bigint, p_screenshot_hash text DEFAULT NULL, p_wifi_audience_count integer DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql AS $$ DECLARE v_tv record; v_campaign_slot record; v_pop_id uuid; BEGIN SELECT * INTO v_tv FROM public.tvs WHERE identifier = p_tv_identifier; SELECT * INTO v_campaign_slot FROM public.campaign_slots WHERE slot_id = p_slot_id AND is_played = false LIMIT 1; INSERT INTO public.proof_of_plays (slot_id, tv_id, campaign_slot_id, played_at, duration, screenshot_hash, wifi_audience_count, is_verified, verified_at, created_at) VALUES (p_slot_id, v_tv.id, v_campaign_slot.id, p_timestamp, 30, p_screenshot_hash, p_wifi_audience_count, true, now_utc(), now_utc()) RETURNING id INTO v_pop_id; UPDATE public.campaign_slots SET is_played = true, proof_of_play_id = v_pop_id, played_at = p_timestamp WHERE id = v_campaign_slot.id; UPDATE public.tv_slots SET status = 'completed', has_proof_of_play = true, proof_of_play_id = v_pop_id, actual_audience = p_wifi_audience_count, updated_at = now_utc() WHERE id = p_slot_id; RETURN jsonb_build_object('proof_of_play_id', v_pop_id); END $$;

-- Notifications
CREATE OR REPLACE FUNCTION api.send_notification(p_user_id uuid, p_type notification_type, p_title text, p_body text, p_data jsonb DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE v_id uuid; BEGIN INSERT INTO public.notifications (user_id, type, title, body, data, created_at) VALUES (p_user_id, p_type, p_title, p_body, p_data, now_utc()) RETURNING id INTO v_id; RETURN v_id; END $$;

CREATE OR REPLACE FUNCTION api.mark_notification_read(p_notification_id uuid) RETURNS jsonb LANGUAGE plpgsql AS $$ BEGIN UPDATE public.notifications SET is_read = true, read_at = now_utc() WHERE id = p_notification_id; RETURN jsonb_build_object('success', true); END $$;

CREATE OR REPLACE FUNCTION api.get_notifications(p_user_id uuid, p_limit integer DEFAULT 50) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT COALESCE(jsonb_agg(to_jsonb(n) ORDER BY n.created_at DESC), '[]'::jsonb) FROM (SELECT * FROM public.notifications WHERE user_id = p_user_id ORDER BY created_at DESC LIMIT p_limit) n $$;

CREATE OR REPLACE FUNCTION api.get_unread_count(p_user_id uuid) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT jsonb_build_object('unread_count', COUNT(*)) FROM public.notifications WHERE user_id = p_user_id AND is_read = false $$;

-- Queries / HTTP helpers
CREATE OR REPLACE FUNCTION api.find_tv_by_identifier(p_identifier text) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT COALESCE(to_jsonb(t), '{}'::jsonb) FROM public.tvs t WHERE t.identifier = p_identifier $$;

CREATE OR REPLACE FUNCTION api.get_device_config(p_identifier text) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$ DECLARE v_tv record; v_location record; v_slots jsonb; BEGIN SELECT * INTO v_tv FROM public.tvs WHERE identifier = p_identifier; SELECT * INTO v_location FROM public.locations WHERE id = v_tv.location_id; SELECT jsonb_agg(jsonb_build_object('id', s.id, 'start_time', s.start_time, 'end_time', s.end_time, 'status', s.status, 'campaign_id', s.campaign_id) ORDER BY s.start_time) INTO v_slots FROM public.tv_slots s WHERE s.tv_id = v_tv.id AND s.date = CURRENT_DATE; RETURN jsonb_build_object('tv', jsonb_build_object('id', v_tv.id, 'name', v_tv.name, 'identifier', v_tv.identifier, 'slot_duration', v_tv.slot_duration, 'timezone', COALESCE(v_location.timezone, 'America/Sao_Paulo')), 'location', CASE WHEN v_location.id IS NOT NULL THEN jsonb_build_object('name', v_location.name, 'city', v_location.city, 'state', v_location.state) ELSE NULL END, 'slots', COALESCE(v_slots, '[]'::jsonb)); END $$;

CREATE OR REPLACE FUNCTION api.get_device_slots(p_identifier text) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT COALESCE(jsonb_agg(jsonb_build_object('id', s.id, 'start_time', s.start_time, 'end_time', s.end_time, 'status', s.status) ORDER BY s.start_time), '[]'::jsonb) FROM public.tv_slots s JOIN public.tvs t ON t.id = s.tv_id WHERE t.identifier = p_identifier AND s.date = CURRENT_DATE $$;

CREATE OR REPLACE FUNCTION api.get_wallet_balance(p_user_id uuid) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT COALESCE(to_jsonb(w), '{}'::jsonb) FROM public.wallets w WHERE w.user_id = p_user_id $$;

CREATE OR REPLACE FUNCTION api.get_platform_revenue(p_start_date date DEFAULT CURRENT_DATE - 30, p_end_date date DEFAULT CURRENT_DATE) RETURNS jsonb LANGUAGE SQL STABLE AS $$ SELECT jsonb_build_object('total_distributed', COALESCE(SUM(total_amount), 0), 'total_splits', COUNT(*)) FROM public.revenue_splits WHERE is_distributed = true AND created_at >= EXTRACT(EPOCH FROM p_start_date)::bigint * 1000 AND created_at <= (EXTRACT(EPOCH FROM p_end_date)::bigint * 1000) + 86399999 $$;

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA api TO anon, authenticated, service_role;
